/* Research-backed explanation. No model training is executed in the browser. */
function blueprintDocument(){const path=ENGINEERING_DIR+'15-dataset-training-blueprint.md',d=DOSSIER.find(d=>d.path===path);return `<details class="technical-detail"><summary>Đọc đầy đủ: file schema, loss/gradient routes và protocol</summary><div class="detail-body"><article class="document-reader">${renderMarkdown(d.markdown,path)}</article></div></details>`;}
function renderDatasetBlueprint(){return head('DATASET · TÍN HIỆU & CÁCH TẠO','Dữ liệu chứa gì?<br>Model học gì từ đó?','Chọn supervision trước, chọn cách thu hoặc sinh sau. Synthetic là cách tạo; latent là biểu diễn được encoder tạo ra.')+
 `<div class="blue-axis"><div><span>01 · NGUỒN GỐC</span><strong>Robot · Human · Simulator</strong></div><b>×</b><div><span>02 · CÁCH TẠO</span><strong>Record · Augment · Generate</strong></div><b>×</b><div><span>03 · TÍN HIỆU</span><strong>RGB · Text · State · Action · Pose</strong></div></div>`+
 `<section class="blue-workbench"><span class="eyebrow">CHỌN TÍN HIỆU ĐỂ XEM ĐƯỜNG HỌC</span><div class="blue-tabs" role="group" aria-label="Tín hiệu dataset">${TRAINING_BLUEPRINT.signals.map((s,i)=>`<button type="button" data-blue-signal="${i}" aria-pressed="${i===0}" aria-controls="blue-signal-detail"><span>${esc(s.icon)}</span>${esc(s.label)}</button>`).join('')}</div><div id="blue-signal-detail" aria-live="polite"></div></section>`+
 `<section class="blue-creation"><div class="blue-section-title"><span class="eyebrow">CÁCH TẠO · KHÔNG PHẢI BỐN MODALITIES</span><h2>Cùng một schema, nhiều cách tạo dữ liệu.</h2></div><div class="blue-create-grid">${TRAINING_BLUEPRINT.creation.map((c,i)=>`<article><span class="blue-counter">0${i+1}</span><small>${esc(c.tag)}</small><h3>${esc(c.name)}</h3><p>${esc(c.body)}</p></article>`).join('')}</div></section>`+
 `<section class="panel blue-latent"><div><span class="eyebrow">REPRESENTATION · DERIVED</span><h2>Latent có “hộ chiếu” encoder.</h2></div><div><p>Pixels → encoder đã pin → vectors / tokens.</p><p class="small">Visual features ≠ latent actions ≠ video VAE latents. Cache giữ checkpoint, processor, layer và shape; đổi encoder phải kiểm lại.</p></div></section>`+
 `<div class="blue-links"><a class="button" href="#learning">Xem dữ liệu đi qua model →</a><a href="#research">So cách training của 7 model →</a></div>`+blueprintDocument();}
function renderTrainingSurvey(){return head('KHẢO SÁT · TRAINING RECIPES','Cùng dữ liệu.<br>Khác target, khác cách học.','Đối chiếu VLA, future conditioning, video generator, WAM và dynamics model. Nguồn tác giả đã đọc; chưa là kết quả native của project.')+
 `<p class="blue-note"><strong>Đường MVP:</strong> GR00T N1.5 qua FluxVLA, R rồi R+S_exec. Human wrist và FOCA là candidates có gate; generator offline và WAM/dynamics là các vai trò khác, không mặc định cùng phạm vi triển khai.</p>`+
 `<section class="blue-workbench survey-workbench"><div class="blue-section-title"><span class="eyebrow">7 MODEL / PHƯƠNG PHÁP · KIỂM 06.10.2026</span><h2>Chọn model để đọc training → inference.</h2></div><div class="blue-tabs model-tabs" role="group" aria-label="Model khảo sát">${TRAINING_BLUEPRINT.models.map((m,i)=>`<button type="button" data-blue-model="${i}" aria-pressed="${i===0}" aria-controls="blue-model-detail">${esc(m.name)}<small>${esc(m.family)}</small></button>`).join('')}</div><div id="blue-model-detail" aria-live="polite"></div></section>`+
 `<section class="blue-model-map"><article><span>VLA / AUXILIARY</span><h3>Học policy từ demonstrations</h3><p>Pretrained VLM + control objective.<br>Future features có thể là auxiliary target.</p></article><article><span>VIDEO WORLD MODEL</span><h3>Tạo dữ liệu offline</h3><p>Generate video → QA → video loss<br>hoặc pseudo-label route riêng.</p></article><article><span>WAM / DYNAMICS</span><h3>Đổi cách học và runtime</h3><p>Joint video/action prediction hoặc<br>dynamics + imagined actor learning.</p></article></section>`+
 `<section class="panel blue-foca"><span class="eyebrow">MỚI BỔ SUNG · FOCA</span><h2>Action-free ở nhánh video.<br>Robot actions vẫn học control.</h2><p>Future targets chỉ ở training. So sánh few-shot phải tính cả generated data và compute.</p><p>${ext('https://arxiv.org/html/2606.20867v1','Paper gốc · §3–5 / Table 2')} · ${ext('https://github.com/cair-vinuni/FOCA','Code & tình trạng release')}</p></section>`+
 `<details class="technical-detail"><summary>Catalog đầy đủ · ${RESEARCH.length} phương pháp & nền tảng</summary><div class="detail-body research-grid">${RESEARCH.map(m=>`<article class="research-card"><div class="research-top"><h2>${esc(m.name)}</h2><span>${esc(m.year)}</span></div><p class="priority">${esc(m.priority)}</p><dl><dt>Input</dt><dd>${esc(m.input)}</dd><dt>Cơ chế</dt><dd>${esc(m.mechanism)}</dd><dt>Áp dụng</dt><dd>${esc(m.reuse)}</dd><dt>Giới hạn</dt><dd>${esc(m.limit)}</dd></dl>${ext(m.url,'Nguồn chính thức')}</article>`).join('')}</div></details>`+
 blueprintDocument()+`<details class="technical-detail"><summary>Evidence register · versions và phạm vi</summary><div class="detail-body"><article class="document-reader">${renderMarkdown(DOSSIER.find(d=>d.path===ENGINEERING_DIR+'09-nguon-va-bang-chung.md').markdown,ENGINEERING_DIR+'09-nguon-va-bang-chung.md')}</article></div></details>`+next('learning','Xem training solution của project');}
function initTrainingBlueprint(signal){const root=document.querySelector('#blue-signal-detail'),model=document.querySelector('#blue-model-detail');if(!root&&!model)return;
 function drawSignal(i){const s=TRAINING_BLUEPRINT.signals[i];root.innerHTML=`<div class="blue-detail-title"><h2>${esc(s.title)}</h2><span>SUPERVISION VIEW · ${esc(s.id.toUpperCase())}</span></div><div class="blue-pipeline"><article><span>01 · FILES</span><div class="blue-file-icon">▤</div><h3>Dataset trên đĩa</h3><p>${esc(s.files)}</p></article><article><span>02 · TENSORS</span><div class="blue-file-icon">▦</div><h3>Conditioning & target</h3><p>${esc(s.tensor)}</p></article><article><span>03 · LOSS → MODULES</span><div class="blue-file-icon">↻</div><h3>Đường gradient</h3><p>${esc(s.loss)}</p><small>${esc(s.modules)}</small></article></div><div class="blue-methods"><strong>Cách có thể tạo:</strong>${s.methods.map(x=>`<span>${esc(x)}</span>`).join('')}</div><p class="blue-gate">${esc(s.gate)}</p>`;document.querySelectorAll('[data-blue-signal]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.blueSignal)===i)));}
 function drawModel(i){const m=TRAINING_BLUEPRINT.models[i];model.innerHTML=`<div class="blue-detail-title"><div><span class="eyebrow">${esc(m.family)} · ${esc(m.version)}</span><h2>${esc(m.name)} <small>${esc(m.tag)}</small></h2></div>${ext(m.url,'Nguồn gốc')}</div><div class="blue-pipeline"><article><span>01 · DATASET</span><h3>Dữ liệu có gì?</h3><p>${esc(m.input)}</p><small><strong>Target:</strong> ${esc(m.target)}</small></article><article><span>02 · TRAINING</span><h3>Model cập nhật gì?</h3><p>${esc(m.train)}</p></article><article><span>03 · INFERENCE</span><h3>Khi chạy cần gì?</h3><p>${esc(m.inference)}</p><small><strong>Evaluation:</strong> ${esc(m.evaluation)}</small></article></div><p class="blue-gate"><strong>Bài học cho A1:</strong> ${esc(m.takeaway)}</p>`;document.querySelectorAll('[data-blue-model]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.blueModel)===i)));}
 document.querySelector('main').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.blueSignal!==undefined)drawSignal(Number(b.dataset.blueSignal));if(b.dataset.blueModel!==undefined)drawModel(Number(b.dataset.blueModel));},{signal});if(root)drawSignal(0);if(model)drawModel(0);
}
